{
  "format_version": 3,
  "flavours": {
    "subject": {
      "id_prefix": "SUB-",
      "body": "required",
      "description": "Fixture subject",
      "use_when": [
        "Fixture root"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        }
      }
    },
    "support": {
      "id_prefix": "SUP-",
      "body": "required",
      "description": "Fixture support",
      "use_when": [
        "Fixture related item"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        },
        "amount": {
          "type": "integer"
        },
        "text": {
          "type": "string"
        },
        "flag": {
          "type": "boolean"
        },
        "score": {
          "type": "number"
        },
        "absent": {
          "type": "string"
        },
        "alias": {
          "type": "string"
        }
      }
    }
  },
  "relations": {
    "supports": {
      "description": "Fixture support relation",
      "source": [
        "support"
      ],
      "target": [
        "subject"
      ],
      "inverse": "supported_by"
    },
    "parent": {
      "description": "Fixture upward ancestry",
      "source": [
        "subject"
      ],
      "target": [
        "subject"
      ],
      "inverse": "children"
    },
    "decomposes_to": {
      "description": "Fixture decomposition",
      "source": [
        "subject"
      ],
      "target": [
        "subject"
      ],
      "inverse": "decomposed_from"
    },
    "supersedes": {
      "description": "Fixture supersession",
      "source": [
        "subject"
      ],
      "target": [
        "subject"
      ],
      "inverse": "superseded_by"
    }
  }
}

{
  "format_version": 3,
  "definitions": [
    {
      "id": "urn:fixture:query:supports",
      "required_fact_sources": ["documents"],
      "support_columns": ["edge"],
      "source_columns": ["support_source"],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "support": {
          "type": "item",
          "flavours": [
            "support"
          ]
        },
        "lifecycle": {
          "type": "text"
        },
        "amount": {
          "type": "integer"
        },
        "text": {
          "type": "text"
        },
        "flag": {
          "type": "boolean"
        },
        "score": {
          "type": "number"
        },
        "absent": {
          "type": "text",
          "optional": true
        }
      },
      "parameters": {
        "state": {
          "type": "text",
          "required": true
        }
      },
      "select": "PREFIX r: <urn:mara:relation:>\nPREFIX f: <urn:mara:field:>\nSELECT ?root ?support ?support_source ?edge ?lifecycle ?amount ?text ?flag ?score ?absent WHERE {\n { ?root r:supported_by ?support } UNION { ?support r:supports ?root }\n ?edge <urn:mara:query:source> ?support ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> r:supports .\n BIND(?support AS ?support_source)\n ?support f:status ?lifecycle ; f:amount ?amount ; f:text ?text ; f:flag ?flag ; f:score ?score .\n OPTIONAL { ?support f:absent ?absent }\n FILTER(sameTerm(?state, \"\") || sameTerm(?lifecycle, ?state))\n}"
    },
    {
      "id": "urn:fixture:query:ancestry",
      "required_fact_sources": ["documents"],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "ancestor": {
          "type": "item",
          "flavours": [
            "subject"
          ]
        },
        "lifecycle": {
          "type": "text"
        }
      },
      "select": "PREFIX r: <urn:mara:relation:>\nPREFIX f: <urn:mara:field:>\nSELECT ?root ?ancestor ?lifecycle WHERE {\n ?root r:parent+ ?ancestor . FILTER(!sameTerm(?root, ?ancestor))\n ?ancestor f:status ?lifecycle\n}"
    },
    {
      "id": "urn:fixture:query:forward",
      "required_fact_sources": ["documents"],
      "root_flavours": [
        "support"
      ],
      "columns": {
        "subject": {
          "type": "item",
          "flavours": [
            "subject"
          ]
        }
      },
      "select": "SELECT ?root ?subject WHERE { ?root <urn:mara:relation:supports> ?subject }"
    },
    {
      "id": "urn:fixture:query:optional",
      "required_fact_sources": ["documents"],
      "root_flavours": [
        "subject"
      ],
      "columns": {
        "absent": {
          "type": "text",
          "optional": true
        }
      },
      "select": "SELECT ?root ?absent WHERE { ?root <urn:mara:relation:supported_by> ?support . OPTIONAL { ?support <urn:mara:field:absent> ?absent } }"
    }
  ]
}
